from pathlib import Path
import json,html,shutil,hashlib
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'public/wildlife';OUT.mkdir(parents=True,exist_ok=True)
species=json.loads((ROOT/'data/species.json').read_text());sources=json.loads((ROOT/'data/sources.json').read_text());records=json.loads((ROOT/'data/checklist-records.json').read_text())
illustrations=json.loads((ROOT/'data/illustrations.json').read_text())
photos=json.loads((ROOT/'data/photos.json').read_text())
E=lambda s:html.escape(str(s),quote=True)
BASE='/wildlife/';ORIGIN='https://shima-craft.com';groupNames=['哺乳類','鳥類','爬虫類','両生類','昆虫'];islands=['奄美大島','加計呂麻島','請島','与路島','喜界島','徳之島','沖永良部島','与論島']
def source_list(ids):return '<ul class="source-list">'+''.join(f'<li><a href="{E(sources[k]["url"])}" target="_blank" rel="noopener noreferrer">{E(sources[k]["title"])} <span aria-label="新しいタブ">↗</span></a></li>' for k in ids)+'</ul>'
def img(s,cls='',lazy=True):
 return f'<img class="{cls}" src="{BASE}assets/animals/{s["asset"]}.webp" alt="" width="{illustrations[s["asset"]]["width"]}" height="{illustrations[s["asset"]]["height"]}" loading="{"lazy" if lazy else "eager"}" decoding="async">' if s['asset'] else ''
def card(s):
 art=img(s,'card-animal') if s['asset'] else '<span class="pending-art">イラスト制作中</span>'
 return f'<li class="species-card {"text-card" if not s["asset"] else ""}" data-id="{s["id"]}"><a href="{BASE}species/{s["id"]}/"><div class="card-art">{art}</div><div class="card-copy"><span class="eyebrow">{s["group"]} / {s["habitat"]}</span><h3>{s["name"]}</h3><p>{s["lead"]}</p><span class="card-arrow" aria-hidden="true">↗</span></div></a></li>'
def shell(title,body,path='',description='奄美群島の生き物を、ゆるかわなイラストと出典つきの解説で。森から海、渡り鳥まで。'):
 page_title=(title+'｜SHIMA CRAFT') if title=='奄美大島の生き物大全' else (title+'｜奄美大島の生き物大全・SHIMA CRAFT')
 return f'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(page_title)}</title><meta name="description" content="{E(description)}"><meta name="theme-color" content="#ffffff"><meta property="og:title" content="{E(title)}｜奄美大島の生き物大全"><meta property="og:type" content="website"><meta property="og:description" content="{E(description)}"><meta property="og:url" content="{ORIGIN}{BASE}{path}"><meta property="og:image" content="{ORIGIN}{BASE}assets/habitat.webp"><link rel="canonical" href="{ORIGIN}{BASE}{path}"><link rel="stylesheet" href="{BASE}assets/style.css"><script src="{BASE}assets/app.js" defer></script></head><body><a href="#main" class="skip">本文へ</a><header class="site-header"><a class="brand" href="{BASE}" aria-label="奄美大島の生き物大全 ホーム"><span>奄美大島の生き物大全<small translate="no">AMAMI WILDLIFE / SHIMA CRAFT</small></span></a><nav aria-label="メインナビゲーション"><a href="{BASE}#explore">絵からさがす</a><a href="{BASE}#catalog">図鑑をひらく</a><a href="{BASE}about/">この図鑑について</a></nav><a class="back-site" href="https://shima-craft.com/">SHIMA CRAFTへ <span aria-hidden="true">↗</span></a></header><main id="main">{body}</main><footer class="site-footer"><div><a class="footer-name" href="{BASE}">奄美大島の生き物大全</a><p>奄美の生き物を知る<br>島の自然を次の世代へ</p></div><nav aria-label="フッターナビゲーション"><a href="https://shima-craft.com/">AMAMI LIFE・島の今日 ↗</a><a href="https://shima-craft.com/studio">SHIMA CRAFT・制作のご案内 ↗</a><a href="{BASE}research/">収録状況・出典</a><a href="{BASE}about/">観察のやくそく・このサイト</a><a href="https://shima-craft.com/privacy">プライバシー</a></nav><p class="colophon">© SHIMA CRAFT <span translate="no">/ AMAMI WILDLIFE</span><br>イラストは特徴を簡略化したAI生成の絵です。野外での同定・安全判断には使用しないでください。</p></footer></body></html>'''
def write(path,text):
 p=OUT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
positions=[('lidths-jay',23,30),('amami-rabbit',20,72),('amami-ishikawa-frog',48,60),('green-turtle',82,68),('camponotus-amamianus',38,84)]
hotspots=''
for id,x,y in positions:
 s=next(s for s in species if s['id']==id)
 hotspots+=f'<a class="scene-animal scene-{id}" href="{BASE}species/{id}/" aria-label="{s["name"]}のページへ">{img(s,"",False)}<span>{s["name"]} <b aria-hidden="true">↗</b></span></a>'
options=lambda items:''.join(f'<option value="{E(v)}">{E(v)}</option>' for v in items)
body=f'''<section class="intro wrap"><div><p class="eyebrow">奄美群島の動物図鑑</p><h1>奄美大島の<br>生き物大全</h1><p class="intro-copy">奄美群島の動物をイラストと写真で紹介<br>島やすみかから気になる生き物を探せます</p><a class="primary-button" href="#catalog">図鑑をひらく <span aria-hidden="true">↘</span></a></div><div class="intro-note"><span class="note-number">01 — 08</span><p>奄美群島の<br><strong>いきものと、ひとやすみ。</strong></p><span class="hand-line" aria-hidden="true"></span><small>奄美大島から、与論島まで。</small></div></section>
<section class="explore wrap" id="explore" aria-labelledby="explore-title"><div class="section-top"><div><p class="eyebrow">イラストから探す</p><h2 id="explore-title">森から海へ 生き物を探そう</h2></div><div class="scene-controls"><button type="button" id="day-toggle" aria-pressed="false">夜の色にする</button><button type="button" id="motion-toggle" aria-pressed="false">動きを止める</button></div></div><p class="scene-hint">生き物を選ぶと写真や特徴を見られます</p><div class="landscape"><img class="scene-background" src="{BASE}assets/habitat.webp" width="1536" height="1024" alt="森から川、マングローブ、海へとつながる、想像の奄美の風景" fetchpriority="high">{hotspots}<span class="scene-tag forest-tag" aria-hidden="true">もり</span><span class="scene-tag sea-tag" aria-hidden="true">うみ</span><span class="scene-glow" aria-hidden="true"></span></div><p class="fine scene-caption">風景・配置・大きさはイメージです。生息地点や、同時に見られることを示すものではありません。</p><div class="animal-shortcuts" aria-label="風景の生き物の一覧">{''.join(f'<a href="{BASE}species/{id}/">{next(s["name"] for s in species if s["id"]==id)} ↗</a>' for id,x,y in positions)}</div></section>
<section class="catalog wrap" id="catalog" aria-labelledby="catalog-title"><div class="section-top"><div><p class="eyebrow">名前や島で調べる</p><h2 id="catalog-title">生き物を探す</h2></div><p class="catalog-note">まずは <strong>{len(species)}</strong> 項目から。<br><a href="{BASE}research/">全種の照合・イラスト追加を進めています ↗</a></p></div><form id="filters" class="filters" role="search"><div class="search-field"><label for="q">名前・学名でさがす</label><div><span aria-hidden="true">⌕</span><input id="q" name="q" type="search" autocomplete="off" placeholder="例：ルリカケス、カエル…"></div></div><div><label for="group">なかま</label><select id="group" name="group"><option value="">すべてのなかま</option>{options(groupNames)}</select></div><div><label for="island">島</label><select id="island" name="island"><option value="">すべての島・沿岸域</option>{options(islands)}</select></div><div><label for="habitat">すみか</label><select id="habitat" name="habitat"><option value="">すべてのすみか</option>{options(['森','川・水辺','里','海・海岸'])}</select></div><div><label for="season">渡り鳥</label><select id="season" name="season"><option value="">すべて</option>{options(['冬鳥','夏鳥','旅鳥'])}</select></div><button class="filter-submit" type="submit">さがす</button></form><noscript><p class="notice">JavaScriptが無効のため、絞り込みは利用できません。下の一覧から生き物のページを開けます。</p></noscript><div class="results-meta"><p id="result-count" role="status" aria-live="polite">{len(species)}項目</p><button id="reset-filters" type="button" hidden>絞り込みをリセット</button></div><p id="island-note" class="fine" hidden>島ごとの根拠を確認できた項目だけを表示しています。表示されない種が、その島にいないという意味ではありません。</p><ul class="species-grid" id="species-grid">{''.join(card(s) for s in species)}</ul><div id="empty" class="empty" hidden><h3>まだ、この図鑑には見つかりませんでした。</h3><p>名前を短くするか、島やなかまの絞り込みを外してみてください。</p><a href="{BASE}research/">文献の記録リストも見る ↗</a></div><button id="show-more" type="button" class="outline-button" hidden>続きをひらく</button></section>
<aside class="promise wrap"><p class="eyebrow">自然観察のマナー</p><h2>生き物の暮らしを<br>大切に</h2><p>距離をとって静かに観察しましょう<br>餌をあげたり追いかけたりしないでください<br>夜の運転では小さな生き物にも気を配りましょう</p><a href="{BASE}about/">観察のやくそくを読む ↗</a></aside>'''
write('index.html',shell('奄美大島の生き物大全',body))
for idx,s in enumerate(species):
 art=img(s,'detail-animal',False) if s['asset'] else '<div class="no-illustration"><span>この子のイラストは<br>ただいま制作中。</span></div>'
 photo=photos.get(s['id'])
 if photo:
  actual=f'<figure class="photo-figure"><img src="{photo["src"]}" width="{photo["width"]}" height="{photo["height"]}" alt="{s["name"]}の実際の写真" loading="lazy" decoding="async"><figcaption>{E(photo["caption"])}<br>写真：{E(photo["title"])}<br>撮影：{E(photo["author"])} / <a href="{E(photo["licenseUrl"])}" target="_blank" rel="noopener noreferrer">{E(photo["license"])}</a><br><a href="{E(photo["sourcePage"])}" target="_blank" rel="noopener noreferrer">写真の出典 ↗</a> · {E(photo["modification"])}</figcaption></figure>'
 else:
  actual='<div class="no-illustration"><span>実際の写真は準備中です<br>掲載できる写真と利用条件を確認しています</span></div>'
 gallery=f'<div class="media-gallery"><div class="media-tabs" role="tablist" aria-label="画像の種類"><button type="button" role="tab" id="illustration-tab" aria-controls="illustration-panel" aria-selected="true">1 イラスト</button><button type="button" role="tab" id="photo-tab" aria-controls="photo-panel" aria-selected="false" tabindex="-1">2 実際の写真</button></div><div class="detail-art" id="illustration-panel" role="tabpanel" aria-labelledby="illustration-tab">{art}<span class="plate-number">NO. {idx+1:03}</span></div><div class="photo-panel" id="photo-panel" role="tabpanel" aria-labelledby="photo-tab" hidden>{actual}</div></div>'
 if photo: gallery+=f'<noscript><p><a href="{photo["src"]}">{s["name"]}の写真を開く</a> / 撮影：{E(photo["author"])} / <a href="{E(photo["licenseUrl"])}">{E(photo["license"])}</a> / <a href="{E(photo["sourcePage"])}">出典</a></p></noscript>'
 dist='・'.join(s['islands']) if s['islands'] else '島別分布は照合中（群島内・沿岸域の資料に掲載）'
 others=[x for x in species if x['id']!=s['id'] and x['group']==s['group']][:3]
 if len(others)<3:others=[x for x in species[:5] if x['id']!=s['id']][:3]
 detail=f'''<div class="wrap detail"><nav class="breadcrumbs" aria-label="パンくず"><a href="{BASE}">図鑑のトップ</a><span aria-hidden="true">/</span><a href="{BASE}#catalog">いきもの一覧</a></nav><article><div class="detail-hero">{gallery}<div class="detail-title"><p class="eyebrow">{s['group']} / {s['habitat']}</p><h1>{s['name']}</h1><p class="latin"><i lang="la">{s['scientific']}</i>{'（亜種）' if s['rank']=='subspecies' else ''}</p><p class="detail-lead">{s['lead']}</p><p>{s['fact']}</p><dl><div><dt>資料で確認した島</dt><dd>{dist}</dd></div><div><dt>季節・渡り</dt><dd>{s['season']}</dd></div></dl><p class="fine">島の一覧は資料から確認できた範囲です。出会いやすさ・現在の個体数を保証するものではありません。</p></div></div><div class="detail-bottom"><section><p class="eyebrow">観察メモ</p><h2>観察するときの注意</h2><p>野生の生き物は、少し離れて静かに観察しましょう。採集や接触はせず、希少な生き物の正確な場所は公開しないでください。</p><p class="fine">絵は写真を参考に特徴を簡略化したAI生成イラストです。個体差・雌雄・成長段階のすべては表現していません。野外での同定、食用・毒性の判定には使わないでください。</p></section><section><h2>解説の出典</h2>{source_list(s['sources'])}<p class="fine">出典確認：{s['checked']}<br>{E(s['taxonomyNote']) if s['taxonomyNote'] else '学名は参照資料に基づきます。分類の更新は継続して確認しています。'}</p></section></div></article><section class="related"><h2>関連する生き物</h2><ul class="species-grid">{''.join(card(x) for x in others)}</ul><a class="outline-button" href="{BASE}#catalog">いきもの一覧へ戻る ↗</a></section></div>'''
 write(Path('species')/s['id']/'index.html',shell(s['name'],detail,f'species/{s["id"]}/',s['lead']+' '+s['fact']))

about='''<article class="wrap prose"><p class="eyebrow">ABOUT THIS FIELD NOTE</p><h1>この図鑑について</h1><p class="large-copy">奄美群島に暮らす動物と<br>季節を渡る鳥たち</p><p>「奄美大島の生き物大全」はSHIMA CRAFTがつくる、動物たちへの小さな入口です。奄美大島だけでなく、加計呂麻島、請島、与路島、喜界島、徳之島、沖永良部島、与論島と周辺の島々・海域を対象に、資料の照合とイラスト制作を続けています。</p><h2>収録範囲と今後の追加</h2><p>動物全般の完全な一覧は未完成です。昆虫以外の節足動物、貝、サンゴ、その他の無脊椎動物など、まだ広い範囲の照合が残っています。「未掲載」は「奄美にいない」という意味ではありません。</p><p>渡り鳥の通過・越冬、過去の記録と現在の生息、在来種と外来種、種と亜種はそれぞれ区別して整理します。文献の機械抽出リストは、解説を編集した図鑑の項目と分けています。</p><h2>観察のやくそく</h2><ol><li>追いかけず、触らず、餌をあげず、距離をとる。</li><li>夜の森では静かに。強い光を長く当てず、運転もゆっくり。</li><li>採集しない。地域の立ち入り・利用ルールを確認する。</li><li>巣穴、ねぐら、産卵場所をのぞかず、正確な位置をSNSに載せない。</li><li>毒や危険の有無を、このサイトの絵で判断しない。</li></ol><h2>イラストについて</h2><p>実際の写真と公的資料を参考に、AIで制作したオリジナルのデフォルメイラストです。輪郭や比率を簡略化しており、識別図ではありません。実写写真は撮影者が再利用を許可したものを使用し、各写真に出典とライセンスを表示しています。専門家による全点の形態監修は未実施です。</p><h2>個人情報とアクセス計測</h2><p>この図鑑独自のアクセス解析タグや広告は設置していません。「動きを止める」設定だけを、この端末のブラウザに保存します。Googleアカウントや会員登録は不要です。配信基盤のログなどについてはSHIMA CRAFTのプライバシーポリシーもご覧ください。</p><div class="prose-actions"><a class="primary-button" href="/wildlife/research/">収録状況と出典を読む ↗</a><a href="https://shima-craft.com/">SHIMA CRAFT・AMAMI LIFEへ ↗</a></div></article>'''
write('about/index.html',shell('この図鑑について',about,'about/'))
coverage=[('哺乳類・爬虫類・両生類','代表種を編集。全群島・外来種・海棲哺乳類の照合は未完了'),('鳥類','代表種と夏鳥・冬鳥を編集。旅鳥・迷鳥・訂正記録・島別目録の統合は未完了'),('昆虫','代表種を編集。トンボの資料を抽出中。アリ・甲虫・蛾等の全目録は未完了'),('魚類','徳之島・沖永良部島の2文献から候補記録を抽出。現行分類・重複・記録の妥当性は未照合'),('その他の無脊椎動物','カニ・エビ・クモ・貝・サンゴ・棘皮動物・環形動物・海綿などは資料収集段階')]
research=f'''<article class="wrap prose research"><p class="eyebrow">RESEARCH NOTE / 更新 2026.11.01</p><h1>収録状況と出典</h1><p class="large-copy">全種の収録に向けて<br>文献と記録を照合しています</p><div class="research-stats"><div><strong>{len(species)}</strong><span>編集済みの項目<br>種・亜種を含む</span></div><div><strong>{sum(bool(s['asset']) for s in species)}</strong><span>イラスト掲載<br>形態の専門監修は未実施</span></div><div><strong>{len(records):,}</strong><span>文献の抽出記録<br>重複・未同定・未照合を含む</span></div></div><p class="notice">全動物の網羅は未達成です。文献の抽出件数は、生息する種数でも、現在の確認個体数でもありません。古い記録・誤同定の注記・亜種・未同定名を含むため、照合前の件数を合算して「全種数」とは扱いません。</p><h2>分野ごとの収録状況</h2><dl class="coverage">{''.join(f'<div><dt>{a}</dt><dd>{b}</dd></div>' for a,b in coverage)}</dl><h2>文献の記録リスト</h2><p>資料の見出しから抽出した、調査用の候補リストです。学名は原文表記のままです。島名は参照資料の対象範囲を示し、現在の生息を断定しません。和名のローマ字を自動で日本語に推測変換していません。</p><a class="outline-button" download href="{BASE}data/checklist-records.csv">調査用リストをCSVでダウンロード ↓</a><form id="record-filter" class="record-search" role="search"><label for="record-q">文献リスト内を検索</label><input id="record-q" type="search" name="record-q" autocomplete="off" placeholder="例：Anguilla、トンボ…"><button type="submit">検索</button></form><p id="record-count" role="status" aria-live="polite">リストは検索または下のボタンで表示できます。</p><button id="load-records" type="button" class="outline-button">文献リストを表示</button><div class="table-scroll"><table id="record-table" hidden><caption>未照合の文献記録（1ページ50件）</caption><thead><tr><th scope="col">原文の名前</th><th scope="col">資料の対象島</th><th scope="col">出典・PDFページ</th></tr></thead><tbody></tbody></table></div><button id="more-records" type="button" class="outline-button" hidden>次の50件を表示</button><noscript><p>CSVファイルで全抽出記録を確認できます。</p></noscript><h2>出典一覧</h2>{source_list(sources.keys())}<p class="fine">参考資料と実写写真の著作権は各権利者に帰属します。実写写真の撮影者・ライセンスは詳細ページに表示しています。</p></article>'''
write('research/index.html',shell('収録状況・出典',research,'research/'))
write('404.html',shell('ページが見つかりません','<section class="wrap prose"><h1>ページが見つかりません</h1><p>URLを確認するか、図鑑のトップから探してください。</p><a class="primary-button" href="/wildlife/">図鑑のトップへ戻る ↗</a></section>'))
for name in ['species.json','sources.json','checklist-records.json','checklist-records.csv','photos.json']:
 (OUT/'data').mkdir(exist_ok=True);shutil.copyfile(ROOT/'data'/name,OUT/'data'/name)
paths=['','about/','research/']+[f'species/{s["id"]}/' for s in species]
write('sitemap.xml','<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{ORIGIN}{BASE}{p}</loc></url>' for p in paths)+'</urlset>')
(ROOT/'public/robots.txt').write_text('User-agent: *\nAllow: /wildlife/\nSitemap: https://shima-craft.com/wildlife/sitemap.xml\n')
manifest={str(p.relative_to(ROOT/'public')):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((ROOT/'public').rglob('*')) if p.is_file()}
(ROOT/'docs/build-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(f'Built {len(paths)} pages and {len(manifest)} public files')
